AND tenant_id in (#{query.tenantId}, -1)
AND space_id = #{query.spaceId}
AND catalog_type = #{query.catalogType}
AND catalog_name LIKE
#{query.catalogName}
AND bot_id in (#{query.botId}, -1)
ORDER BY a.sortby, a.created_time

