SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_catalog
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND par_catalog_id = #{parCatalogId}
  AND catalog_type = #{catalogType}
